create table if not exists public.site_content (id bigint primary key, content jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now()); alter table public.site_content enable row level security; create policy "Public can read portfolio content" on public.site_content for select using (true); create policy "Authenticated users can update portfolio content" on public.site_content for all to authenticated using (true) with check (true); insert into public.site_content(id,content) values (1,'{"name":"Kero","role":"DEVELOPER & DIGITAL CREATOR","headline":"I DON’T JUST","highlight":"BUILD.","about":"I build digital experiences with a strong visual identity, thoughtful interactions, and details that feel alive.","email":"hello@kero.dev","avatar_url":"","music_url":"","volume":0.28,"skills":["React","TypeScript","UI / UX","Motion Design","Node.js","Creative Coding"],"projects":[{"title":"Digital Systems","category":"WEB EXPERIENCE","description":"A modern digital experience built around clarity, motion and a distinctive visual language.","image_url":"","link":"#"},{"title":"Creative Interface","category":"INTERACTIVE DESIGN","description":"An expressive interface where thoughtful details make the whole experience feel premium.","image_url":"","link":"#"},{"title":"Personal Platform","category":"PORTFOLIO / BRAND","description":"A flexible personal platform designed to evolve with new work and ideas.","image_url":"","link":"#"}],"certificates":[{"title":"Professional Certificate","issuer":"Add your certificate details","image_url":""},{"title":"Learning & Development","issuer":"Add your certificate details","image_url":""}]}') on conflict(id) do nothing; insert into storage.buckets(id,name,public) values('portfolio-assets','portfolio-assets',true) on conflict(id) do nothing; create policy "Public can view portfolio assets" on storage.objects for select using (bucket_id='portfolio-assets'); create policy "Authenticated users can upload portfolio assets" on storage.objects for insert to authenticated with check (bucket_id='portfolio-assets'); create policy "Authenticated users can update portfolio assets" on storage.objects for update to authenticated using (bucket_id='portfolio-assets') with check (bucket_id='portfolio-assets');